async function RANDOM_ELEMENT(frob) {
  return get(frob, random(get(frob, 0)));
}

async function PICK_ONE(frob) {
  let l = get(frob, 0), cnt = get(frob, 1), rnd = 0, msg = 0, rfrob = 0;
  l = l - 1;
  frob = frob + 2;
  rfrob = frob + (cnt * 2);
  rnd = random(l - cnt);
  msg = get(rfrob, rnd);
  put(rfrob, rnd, get(rfrob, 1));
  put(rfrob, 1, msg);
  cnt = cnt + 1;
  if (cnt == l) {
    cnt = 0;
  }
  put(frob, 0, cnt);
  return msg;
}

async function GO() {
  restart: for (;;) {
    putb(g.P_LEXV, 0, 59);
    enable(await QUEUE(I_WIZARD.id, 4));
    await QUEUE(I_LANTERN.id, 200);
    putProp(BALLOON, P.VTYPE, NONLANDBIT);
    putProp(BUCKET, P.VTYPE, NONLANDBIT);
    g.LIT = true;
    g.WINNER = ADVENTURER;
    g.HERE = INSIDE_THE_BARROW;
    g.P_IT_OBJECT = false;
    if (!(hasFlag(g.HERE, TOUCHBIT))) {
      await V_VERSION();
      crlf();
    }
    await V_LOOK();
    await MAIN_LOOP();
    continue restart;
  }
}

async function MAIN_LOOP() {
  let trash = 0;
  for (;;) {
    trash = await MAIN_LOOP_1();
  }
}

async function MAIN_LOOP_1() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = 0, tbl = 0, v_ = 0, ptbl = 0, obj1 = 0, tmp = 0, o = 0, i = 0;
  cnt = 0;
  obj = false;
  ptbl = true;
  if (g.P_WON = await PARSER()) {
    icnt = get(g.P_PRSI, g.P_MATCHLEN);
    ocnt = get(g.P_PRSO, g.P_MATCHLEN);
    if (g.P_IT_OBJECT && (await ACCESSIBLE$(g.P_IT_OBJECT))) {
      tmp = false;
      loop1: for (;;) {
        if ((cnt = cnt + 1) > icnt) {
          break loop1;
        } else {
          if (eq(get(g.P_PRSI, cnt), IT)) {
            put(g.P_PRSI, cnt, g.P_IT_OBJECT);
            tmp = true;
            break loop1;
          }
        }
      }
      if (!tmp) {
        cnt = 0;
        loop2: for (;;) {
          if ((cnt = cnt + 1) > ocnt) {
            break loop2;
          } else {
            if (eq(get(g.P_PRSO, cnt), IT)) {
              put(g.P_PRSO, cnt, g.P_IT_OBJECT);
              break loop2;
            }
          }
        }
      }
      cnt = 0;
    }
    num = ocnt == 0 ? ocnt : (ocnt > 1 ? (tbl = g.P_PRSO, icnt == 0 ? (obj = false) : (obj = get(g.P_PRSI, 1)), ocnt) : (icnt > 1 ? (ptbl = false, tbl = g.P_PRSI, obj = get(g.P_PRSO, 1), icnt) : 1));
    if (!obj && (icnt == 1)) {
      obj = get(g.P_PRSI, 1);
    }
    if ((g.PRSA == V.WALK) && !(g.P_WALK_DIR == 0)) {
      v_ = await PERFORM(g.PRSA, g.PRSO);
    } else if (num == 0) {
      if (div(getb(g.P_SYNTAX, P_SPREP1), 64) == 0) {
        v_ = await PERFORM(g.PRSA);
        g.PRSO = false;
      } else if (!g.LIT) {
        tell(S(g.TOO_DARK), "\n");
      } else {
        tell(S(g.REFERRING));
        v_ = false;
      }
    } else {
      g.P_NOT_HERE = 0;
      g.P_MULT = false;
      if (num > 1) {
        g.P_MULT = true;
      }
      tmp = false;
      loop3: for (;;) {
        if ((cnt = cnt + 1) > num) {
          if (g.P_NOT_HERE > 0) {
            tell("The ");
            if (!(g.P_NOT_HERE == num)) {
              tell("other ");
            }
            tell("object");
            if (!(g.P_NOT_HERE == 1)) {
              tell("s");
            }
            tell(" that you mentioned ");
            if (!(g.P_NOT_HERE == 1)) {
              tell("are");
            } else {
              tell("is");
            }
            tell("n't here.\n");
          } else if (!tmp) {
            tell("There's nothing here you can take.\n");
          }
          break loop3;
        } else {
          if (ptbl) {
            obj1 = get(g.P_PRSO, cnt);
          } else {
            obj1 = get(g.P_PRSI, cnt);
          }
          o = ptbl ? obj1 : obj;
          i = ptbl ? obj : obj1;
          if ((num > 1) || eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL)) {
            v_ = loc(g.WINNER);
            if (o == NOT_HERE_OBJECT) {
              g.P_NOT_HERE = g.P_NOT_HERE + 1;
              continue loop3;
            } else if (isVerb(V.TAKE) && i && eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL) && !(loc(o) == i)) {
              continue loop3;
            } else if ((g.P_GETFLAGS == P_ALL) && isVerb(V.TAKE) && ((!(eq(loc(o), g.WINNER, g.HERE, v_)) && !(eq(loc(o), i)) && !(hasFlag(loc(o), SURFACEBIT))) || !(hasFlag(o, TAKEBIT) || hasFlag(o, TRYTAKEBIT)))) {
              continue loop3;
            } else {
              if (obj1 == IT) {
                printD(g.P_IT_OBJECT);
              } else {
                printD(obj1);
              }
              tell(": ");
            }
          }
          g.PRSO = o;
          g.PRSI = i;
          tmp = true;
          v_ = await PERFORM(g.PRSA, g.PRSO, g.PRSI);
          if (v_ == M_FATAL) {
            break loop3;
          }
        }
      }
    }
    if (!(v_ == M_FATAL)) {
      v_ = await apply(getProp(loc(g.WINNER), P.ACTION), M_END);
    }
    if (v_ == M_FATAL) {
      g.P_CONT = false;
    }
  } else {
    g.P_CONT = false;
  }
  if (g.P_WON) {
    if (isVerb(V.TELL, V.BRIEF, V.SUPER_BRIEF, V.VERBOSE, V.SAVE, V.VERSION, V.QUIT, V.RESTART, V.SCORE, V.SCRIPT, V.UNSCRIPT, V.RESTORE)) {
      return true;
    } else {
      return v_ = await CLOCKER();
    }
  } else {
    return false;
  }
}

async function PERFORM(a_, o = false, i = false) {
  let v_ = 0, oa = 0, oo = 0, oi = 0;
  oa = g.PRSA;
  oo = g.PRSO;
  oi = g.PRSI;
  if ((IT == i || IT == o) && !(await ACCESSIBLE$(g.P_IT_OBJECT))) {
    tell(S(g.REFERRING));
    return M_FATAL;
  }
  if (o == IT) {
    o = g.P_IT_OBJECT;
  }
  if (i == IT) {
    i = g.P_IT_OBJECT;
  }
  g.PRSA = a_;
  g.PRSO = o;
  if (g.PRSO && !(g.PRSI == IT) && !(isVerb(V.WALK))) {
    g.P_IT_OBJECT = g.PRSO;
  }
  g.PRSI = i;
  if ((NOT_HERE_OBJECT == g.PRSO || NOT_HERE_OBJECT == g.PRSI) && (v_ = await NOT_HERE_OBJECT_F())) {
  } else {
    o = g.PRSO;
    i = g.PRSI;
    if (v_ = await apply(getProp(g.WINNER, P.ACTION))) {
    } else if (v_ = await apply(getProp(loc(g.WINNER), P.ACTION), M_BEG)) {
    } else if (v_ = await apply(get(g.PREACTIONS, a_))) {
    } else if (i && (v_ = await apply(getProp(i, P.ACTION)))) {
    } else if (o && !(a_ == V.WALK) && loc(o) && (v_ = await apply(getProp(loc(o), P.CONTFCN)))) {
    } else if (o && !(a_ == V.WALK) && (v_ = await apply(getProp(o, P.ACTION)))) {
    } else if (v_ = await apply(get(g.ACTIONS, a_))) {
    }
  }
  g.PRSA = oa;
  g.PRSO = oo;
  g.PRSI = oi;
  return v_;
}

