async function SPHERE_F() {
  if (isVerb(V.TAKE, V.MOVE, V.PUT) && (g.PRSO == PALANTIR_1) && !g.CAGE_SOLVE_FLAG) {
    if (ADVENTURER == g.WINNER) {
      tell("As you reach for the sphere, a solid steel cage falls to entrap you. Worse, poisonous gas begins seeping in.\n\n");
      if (loc(ROBOT) == g.HERE) {
        move(ROBOT, CAGE);
        setFlag(ROBOT, NDESCBIT);
      }
      await GOTO(CAGE);
      setFlag(CAGE_OBJECT, NDESCBIT);
      clearFlag(CAGE_OBJECT, INVISIBLE);
      enable(await QUEUE(I_CAGE_DEATH.id, 6));
      return move(CAGE_OBJECT, g.HERE);
    } else {
      setFlag(PALANTIR_1, INVISIBLE);
      remove(ROBOT);
      setFlag(g.PRSO, INVISIBLE);
      move(CAGE_OBJECT, DINGY_CLOSET);
      clearFlag(CAGE_OBJECT, INVISIBLE);
      tell("As the robot touches the sphere, a solid steel cage falls from the ceiling, trapping him. You can faintly hear his last words: ", S(g.B_W_C));
      return (await JIGS_UP("\""));
    }
  } else if (isVerb(V.LOOK_INSIDE)) {
    return await PALANTIR_LOOK(g.PRSO == PALANTIR_1 ? PALANTIR_2 : (g.PRSO == PALANTIR_2 ? PALANTIR_3 : (g.PRSO == PALANTIR_3 ? PALANTIR_1 : PALANTIR_4)));
  } else if (isVerb(V.EXAMINE)) {
    tell("There is something misty in the sphere. Perhaps if you were to look into it...\n");
    return true;
  } else {
    return false;
  }
}

async function PALANTIR_LOOK(obj) {
  let rm = 0, l = 0;
  if (obj == PALANTIR_4) {
    tell(S(g.STRANGE_VISION), " a huge and fearful face which peers at you expectantly.\n");
    return true;
  }
  rm = await META_LOC(obj);
  l = loc(obj);
  if (!l || !(await LIT$(rm))) {
    tell(S(g.ONLY_DARKNESS));
  } else if (!(loc(l) == ROOMS)) {
    if (hasFlag(l, OPENBIT)) {
      tell("You see the inside of a ", D(l), S(g.PERIOD_CR));
    } else {
      tell(S(g.ONLY_DARKNESS));
    }
  } else {
    if (g.DEAD) {
      tell("As you peer through the mist, a strangely colored vision of a huge room takes shape");
    } else {
      tell(S(g.STRANGE_VISION), " of a distant room, which can be described clearly");
    }
    tell("...\n\n");
    setFlag(obj, INVISIBLE);
    await GO_LOOK(rm);
    if (g.HERE == rm) {
      tell("An astonished adventurer is staring into a crystal sphere.\n");
    }
    clearFlag(obj, INVISIBLE);
    if (!g.DEAD) {
      tell("The vision fades, revealing only an ordinary crystal sphere.\n");
    }
  }
  return true;
}

async function GO_LOOK(rm) {
  let ohere = 0, olit = 0, oseen = false;
  ohere = g.HERE;
  if (hasFlag(ohere, TOUCHBIT)) {
    oseen = true;
  }
  olit = g.LIT;
  g.HERE = rm;
  g.LIT = await LIT$(rm);
  await V_LOOK();
  if (!oseen) {
    clearFlag(ohere, TOUCHBIT);
  }
  g.HERE = ohere;
  return g.LIT = olit;
}

async function DEAD_PALANTIR_F(rarg) {
  let p_ = 0;
  if (rarg == M_LOOK) {
    tell("You are in a huge crystalline sphere filled with thin ");
    if (g.HERE == DEAD_PALANTIR_1) {
      p_ = PALANTIR_1;
      tell("red");
    } else if (g.HERE == DEAD_PALANTIR_2) {
      p_ = PALANTIR_2;
      tell("blue");
    } else {
      p_ = PALANTIR_3;
      tell("white");
    }
    tell(" mist. The mist becomes ");
    if (g.HERE == DEAD_PALANTIR_1) {
      tell("blue");
    } else if (g.HERE == DEAD_PALANTIR_2) {
      tell("white");
    } else {
      tell("black");
    }
    tell(" to the west. You strain to look out through the mist...\n\n");
    if (hasFlag(p_, TOUCHBIT)) {
      await PALANTIR_LOOK(p_);
    } else if (p_ == PALANTIR_1) {
      tell("You see a small room with a sign, too blurry to read.");
    } else if (p_ == PALANTIR_2) {
      tell("You see a dreary room with an oak door and a huge table. There is an odd glow to the mist.");
    } else if (p_ == PALANTIR_3) {
      tell("A watery room is barely visible.");
      if ((loc(SERPENT) == AQUARIUM) && (25 > random(100))) {
        tell(" A shadow swims by as you look.");
      }
    }
    return crlf();
  } else if ((rarg == M_ENTER) && (g.HERE == DEAD_PALANTIR_4)) {
    if (loc(DEMON) == PENTAGRAM_ROOM) {
      tell("The room is empty. A huge face looks down from outside and laughs sardonically. It doesn't look like you're getting out of this predicament!\n");
      await FINISH();
    }
    tell("A huge and horrible face materializes out of the mist. \"");
    if (!(g.DEATHS < 3)) {
      tell("You again! You'll obviously be no help to me.\" The face disappears and everything goes black.\n");
      await FINISH();
    }
    tell("Perhaps you may be of use in gaining my freedom from this place. I return you to your foolish quest! Mayhap you will repay this favor in kind someday.\" The mist swirls, and you are returned to the world of life.\n");
    g.DEAD = false;
    return await GOTO(INSIDE_THE_BARROW);
  } else {
    return false;
  }
}

