async function I_LANTERN() {
  let tick = 0, tbl = g.LAMP_TABLE;
  enable(await QUEUE(I_LANTERN.id, tick = get(tbl, 0)));
  if (tick == 0) {
    clearFlag(LAMP, ONBIT);
    g.LAMP_BURNED_OUT = true;
  }
  if (await ACCESSIBLE$(LAMP)) {
    if (tick == 0) {
      tell("You'd better have more light than from the ", D(LAMP), S(g.PERIOD_CR));
    } else {
      tell(S(get(tbl, 1)), "\n");
    }
  }
  if (!(tick == 0)) {
    return g.LAMP_TABLE = tbl + 4;
  } else {
    return false;
  }
}

