async function CERBERUS_F() {
  if (isVerb(V.WAVE, V.RUB, V.RAISE) && (g.PRSO == WAND)) {
    tell("The dog looks puzzled.\n");
    return false;
  } else if (g.WAND_ON && isVerb(V.SAY, V.INCANT)) {
    return false;
  } else if (await HELLO$(CERBERUS)) {
    if (g.CERBERUS_LEASHED) {
      tell("\"Arf! Arf!\"\n");
      return true;
    } else {
      tell("\"Grrrr!\"\n");
      return true;
    }
  } else if (isVerb(V.ATTACK, V.MUNG)) {
    if (g.CERBERUS_LEASHED) {
      remove(CERBERUS);
      tell("With a quiet bark of disappointment, the creature expires into a small pile of dust which blows away into nothing.\n");
      return true;
    } else {
      tell("The maddened dog-thing snaps at you viciously.\n");
      return true;
    }
  } else if (isVerb(V.PUT, V.PUT_ON) && (g.PRSO == COLLAR)) {
    g.CERBERUS_LEASHED = true;
    move(COLLAR, CERBERUS);
    setFlag(COLLAR, NDESCBIT);
    setFlag(COLLAR, TRYTAKEBIT);
    putProp(CERBERUS, P.LDESC, "A grinning, three-headed dog, wearing a huge collar, wags its tail here.");
    tell("All three heads begin licking your face, and its huge tail wags enthusiastically, almost blowing you over from the breeze it creates.\n");
    return true;
  } else if (isVerb(V.ENCHANT)) {
    if (g.SPELL_USED == W.FLOAT) {
      g.SPELL_HANDLED$ = true;
      tell("The huge dog rises an inch off the ground, for a moment.\n");
      return true;
    } else if (g.SPELL_USED == W.FEEBLE) {
      tell("What an effect! He now has the strength of just one elephant, rather than ten!\n");
      return true;
    } else {
      return false;
    }
  } else if (!g.CERBERUS_LEASHED) {
    tell("The three-headed dog snaps at you viciously!\n");
    return true;
  } else if (g.CERBERUS_LEASHED && isVerb(V.RUB)) {
    tell("The dog slobbers and whines with uncontained joy.\n");
    return true;
  } else {
    return false;
  }
}

