async function ROBOT_F(rarg = M_OBJECT) {
  if (g.WINNER == ROBOT) {
    if (isVerb(V.SGIVE)) {
      return false;
    } else if (isVerb(V.FOLLOW)) {
      tell("\"I'm too primitive. I can walk in any direction you order, though.\"\n");
      return true;
    } else if (isVerb(V.RAISE, V.TAKE, V.MOVE) && (g.PRSO == CAGE_OBJECT)) {
      tell("The robots pulverizes the cage to dust.\n\n");
      disable(await INT(I_CAGE_DEATH.id));
      g.WINNER = ADVENTURER;
      clearFlag(ROBOT, NDESCBIT);
      setFlag(PALANTIR_1, TAKEBIT);
      move(ROBOT, DINGY_CLOSET);
      g.CAGE_SOLVE_FLAG = true;
      return await GOTO(DINGY_CLOSET);
    } else if (isVerb(V.DROP, V.PUT, V.THROW)) {
      if (!(await ACCESSIBLE$(ROBOT))) {
        return false;
      } else {
        tell(S(g.B_W_C));
        if (loc(g.PRSO) == ROBOT) {
          tell("\"\n");
          return false;
        } else {
          tell(" I don't have that!\"\n");
          return true;
        }
      }
    } else if (isVerb(V.WALK) || (isVerb(V.TAKE, V.PUSH) && !(hasFlag(g.PRSO, ACTORBIT)))) {
      if (!(await ACCESSIBLE$(ROBOT))) {
        return false;
      } else {
        tell(S(g.B_W_C), "\"\n");
      }
      return false;
    } else {
      if (await ACCESSIBLE$(ROBOT)) {
        tell("\"My programming is insufficient for that task.\"\n");
      }
      return true;
    }
  } else if (isVerb(V.OPEN, V.LOOK_INSIDE, V.CLOSE)) {
    tell("The robot has no access panel.\n");
    return true;
  } else if (isVerb(V.GIVE) && (g.PRSI == ROBOT)) {
    move(g.PRSO, ROBOT);
    tell("The robot accepts the ", D(g.PRSO), S(g.PERIOD_CR));
    return true;
  } else if (isVerb(V.THROW, V.MUNG)) {
    tell("The robot (being of shoddy construction) disintegrates before your eyes.\n");
    return remove(isVerb(V.THROW) ? g.PRSI : g.PRSO);
  } else {
    return false;
  }
}

