async function BALLOON_F(rarg = false) {
  let m = 0, r = 0, rc = 0;
  if (rarg == M_LOOK) {
    if (g.BALLOON_INFLATED) {
      tell("The cloth bag is inflated and ");
      if (hasFlag(RECEPTACLE, OPENBIT)) {
        tell("a ", D(g.BALLOON_INFLATED), " is burning in the");
      } else {
        tell("smoke leaks out of the closed");
      }
      tell(" receptacle.");
    } else {
      tell("The cloth bag is draped over the side of the basket. In the middle of the basket is a metal receptacle which is ");
      if (hasFlag(RECEPTACLE, OPENBIT)) {
        tell("open");
        rc = first(RECEPTACLE);
        if (rc) {
          tell(". A ", D(rc), " is ");
          if (g.BALLOON_INFLATED == rc) {
            tell("burning");
          } else {
            tell("nestled");
          }
          tell(" inside");
        }
      } else {
        tell("closed");
      }
      tell(". A braided wire ");
    }
    if (g.BALLOON_TIED) {
      tell("connects the balloon to the hook.");
    } else {
      tell("dangles from the basket.");
    }
    tell(S(g.PERIOD_CR));
    return true;
  } else if (rarg == M_OBJDESC) {
    tell("There is a large heavy wicker basket here. A huge cloth bag is attached to the basket and ");
    if (g.BALLOON_INFLATED) {
      tell("inflated");
    } else {
      tell("and draped over the side");
    }
    tell(". A metal receptacle is fastened to the center of the basket");
    if (g.BALLOON_INFLATED) {
      if (hasFlag(RECEPTACLE, OPENBIT)) {
        tell(". In it is a burning ", D(g.BALLOON_INFLATED));
      } else {
        tell(". Smoke leaks from its closed lid");
      }
    }
    tell(". A piece of braided wire ");
    if (g.BALLOON_TIED) {
      tell("tied to the hook holds the balloon in place.\n");
      return true;
    } else {
      tell("dangles from the basket.\n");
      return true;
    }
  } else if (rarg == M_BEG) {
    if (isVerb(V.WALK)) {
      if (m = getPropAddr(g.HERE, g.PRSO)) {
        if (g.BALLOON_TIED) {
          tell("You are tied to the ledge.\n");
          return true;
        } else {
          eq(propSize(m), 1) && (g.BALLOON_LOC = r);
          enable(await QUEUE(I_BALLOON.id, 3));
          return false;
        }
      } else {
        tell("You can't control the balloon this way.\n");
        return true;
      }
    } else if (isVerb(V.OPEN) && g.BALLOON_INFLATED && (g.PRSO == RECEPTACLE) && first(RECEPTACLE)) {
      setFlag(RECEPTACLE, OPENBIT);
      tell("Opening it reveals a burning ", D(g.BALLOON_INFLATED), S(g.PERIOD_CR));
      return true;
    } else if (isVerb(V.TAKE) && (g.BALLOON_INFLATED == g.PRSO)) {
      tell("You don't really want to hold a burning ", D(g.PRSO), S(g.PERIOD_CR));
      return true;
    } else if (isVerb(V.PUT) && (g.PRSI == RECEPTACLE) && first(RECEPTACLE)) {
      tell("The receptacle is already occupied.\n");
      return true;
    } else if (isVerb(V.PUT) && (g.PRSI == RECEPTACLE)) {
      setFlag(g.PRSO, NDESCBIT);
      return false;
    } else if (isVerb(V.INFLATE)) {
      tell("It takes more than words to inflate a balloon.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function I_BALLOON() {
  if (hasFlag(RECEPTACLE, OPENBIT) && g.BALLOON_INFLATED) {
    return await RISE_AND_SHINE();
  } else if (g.HERE == NARROW_LEDGE || g.HERE == WIDE_LEDGE) {
    return await RISE_AND_SHINE();
  } else {
    return await DECLINE_AND_FALL();
  }
}

async function BALLOON_BURN() {
  tell("The ", D(g.PRSO), " burns inside the receptacle.\n");
  enable(await QUEUE(I_BURNUP.id, getProp(g.PRSO, P.SIZE) * 20));
  setFlag(g.PRSO, FLAMEBIT);
  setFlag(g.PRSO, ONBIT);
  clearFlag(g.PRSO, TAKEBIT);
  clearFlag(g.PRSO, READBIT);
  if (g.BALLOON_INFLATED) {
    return true;
  } else {
    tell("The cloth bag inflates as it fills with hot air.\n");
    if (!g.LABEL_REVEALED) {
      move(BALLOON_LABEL, BALLOON);
      tell("A label drops from the bag into the basket.\n");
    }
    g.LABEL_REVEALED = true;
    g.BALLOON_INFLATED = g.PRSO;
    return enable(await QUEUE(I_BALLOON.id, 3));
  }
}

async function PUT_BALLOON(there, str) {
  if (g.HERE == NARROW_LEDGE || g.HERE == WIDE_LEDGE || g.HERE == VOLCANO_BOTTOM) {
    tell("You watch as the balloon slowly ", S(str), "\n");
  }
  move(BALLOON, there);
  return g.BALLOON_LOC = there;
}

async function RISE_AND_SHINE() {
  let in_ = (loc(g.WINNER) == BALLOON), r = 0;
  enable(await QUEUE(I_BALLOON.id, 3));
  if (g.BALLOON_LOC == VOLCANO_BY_WIDE_LEDGE) {
    disable(await INT(I_BURNUP.id));
    disable(await INT(I_BALLOON.id));
    remove(BALLOON);
    if (in_) {
      (await JIGS_UP("The balloon floats majestically out of the volcano, revealing a breathtaking view of a forest clearing with a white house. High winds carry you into the snow-capped (and jagged) cliffs of the Flathead Mountains!"));
    } else if (g.HERE == NARROW_LEDGE || g.HERE == WIDE_LEDGE || g.HERE == VOLCANO_BOTTOM) {
      tell("You watch the balloon drift over the rim and away on the wind.\n");
    }
    return g.BALLOON_LOC = VOLCANO_BOTTOM;
  } else if (r = await LKP(g.BALLOON_LOC, g.BALLOON_UPS)) {
    if (in_) {
      tell("The balloon ascends.\n\n");
      g.BALLOON_LOC = r;
      return await GOTO(r);
    } else {
      return (await PUT_BALLOON(r, "ascends."));
    }
  } else if (r = await LKP(g.BALLOON_LOC, g.BALLOON_FLOATS)) {
    if (in_) {
      tell("The balloon leaves the ledge.\n\n");
      g.BALLOON_LOC = r;
      return await GOTO(r);
    } else {
      (await PUT_BALLOON(r, "floats, ascending due to its light load."));
      return setFlag(RECEPTACLE, OPENBIT);
    }
  } else if (in_) {
    g.BALLOON_LOC = VOLCANO_CORE;
    tell("The balloon rises slowly from the ground.\n\n");
    return await GOTO(VOLCANO_CORE);
  } else {
    return (await PUT_BALLOON(VOLCANO_CORE, "lifts off."));
  }
}

async function DECLINE_AND_FALL() {
  let in_ = (loc(g.WINNER) == BALLOON), r = 0;
  enable(await QUEUE(I_BALLOON.id, 3));
  if (g.BALLOON_LOC == VOLCANO_CORE) {
    if (in_) {
      g.BALLOON_LOC = VOLCANO_BOTTOM;
      if (g.BALLOON_INFLATED) {
        tell("The balloon has landed.\n\n");
        return await GOTO(VOLCANO_BOTTOM);
      } else {
        remove(BALLOON);
        move(ADVENTURER, g.HERE);
        disable(await INT(I_BALLOON.id));
        tell("The balloon smashes into dust against the volcano floor. You, miraculously, survive.\n\n");
        return await GOTO(VOLCANO_BOTTOM);
      }
    } else {
      return (await PUT_BALLOON(VOLCANO_BOTTOM, "lands."));
    }
  } else if (r = await LKP(g.BALLOON_LOC, g.BALLOON_DOWNS)) {
    if (in_) {
      tell("The balloon descends.\n\n");
      g.BALLOON_LOC = r;
      return await GOTO(r);
    } else {
      return (await PUT_BALLOON(r, "descends."));
    }
  } else {
    return false;
  }
}

async function LKP(itm, tbl) {
  let cnt = 0, len = get(tbl, 0);
  for (;;) {
    if ((cnt = cnt + 1) > len) {
      return false;
    } else if (eq(get(tbl, cnt), itm)) {
      if (cnt == len) {
        return false;
      } else {
        return get(tbl, cnt + 1);
      }
    }
  }
}

